  "gorsel": "<table class=\"tablo\"><tr><th>Düzenek</th><th>Yükü taşıyan ip parçası sayısı</th></tr><tr><td>P</td><td>1</td></tr><tr><td>Q</td><td>4</td></tr><tr><td>R</td><td>2</td></tr><tr><td>S</td><td>3</td></tr></table>",
