  "gorsel": "<table class=\"tablo\"><tr><th>Kaldıraç</th><th>Destek</th><th>Yük</th><th>Kuvvet</th></tr><tr><td>K</td><td>6</td><td>0</td><td>3</td></tr><tr><td>L</td><td>4</td><td>1</td><td>8</td></tr><tr><td>M</td><td>5</td><td>8</td><td>1</td></tr><tr><td>N</td><td>3</td><td>0</td><td>8</td></tr></table>",
